changeSet.sql:
ALTER TABLE public.household ADD COLUMN license_number varchar(100);
ALTER TABLE public.household ADD CONSTRAINT ck_household_facility_type
    CHECK (type IN ('RESIDENTIAL','BUSINESS','BOARDING_HOUSE','RELIGIOUS','SPECIAL'));
CREATE OR REPLACE VIEW tc2_roster.household AS SELECT roster_id id,hamlet_id,code,source_case_number,case_scope,
    owner_name representative_name,owner_phone phone,raw_address,street,alley,origin,verification_status,
    longitude,latitude,coordinate_method,coordinate_seed,boundary_hash,version,created_at,updated_at,
    type,business_name,business_category,license_type,license_number,license_expiry FROM public.household;

rollback.sql:
DROP VIEW tc2_roster.household;
CREATE VIEW tc2_roster.household AS SELECT roster_id id,hamlet_id,code,source_case_number,case_scope,
    owner_name representative_name,owner_phone phone,raw_address,street,alley,origin,verification_status,
    longitude,latitude,coordinate_method,coordinate_seed,boundary_hash,version,created_at,updated_at FROM public.household;
COMMENT ON VIEW tc2_roster.household IS 'Updatable UUID projection of public.household; no duplicated storage';
GRANT SELECT,INSERT,UPDATE,DELETE ON tc2_roster.household TO police_runtime;
ALTER TABLE public.household DROP CONSTRAINT ck_household_facility_type;
ALTER TABLE public.household DROP COLUMN license_number;
